#include "genesis/genesis.hpp"
#include <cstdlib>
#include <iostream>
#include <stdexcept>
void check(bool v,const char*m){if(!v)throw std::runtime_error(m);}genesis::LineageIdentity identity(){genesis::LineageIdentity i;i.organism_id="o";i.genesis_id="g";i.lineage_id="l";i.birth_event_id="b";i.genome_hash="gh";i.inherited_state_hash="s";i.birth_snapshot_hash="bs";i.identity_seed="seed";i.lineage_signature="PENDING_CRYPTO";i.cryptographic_provenance="UNAVAILABLE";return i;}
int main(int argc,char**argv){try{check(argc==2,"registry path required");auto r=genesis::RequirementRegistry::load(argv[1]);check(r.size()>=20,"registry too small");check(r.validate().empty(),"registry invalid");genesis::ProvenanceLedger l;l.append(1,"e1","o","birth","p1");l.append(2,"e2","o","experience","p2");check(l.verify(),"ledger invalid");auto id=identity();check(genesis::validate(id).empty(),"identity invalid");check(genesis::represents_continuation(genesis::OriginKind::restore),"restore semantics");check(!genesis::represents_continuation(genesis::OriginKind::clone),"clone semantics");genesis::Genome g{"genome","1",{{"gene","v","d"}},{{"gene","zygote","always",.5}},id};check(genesis::validate(g).empty(),"genome invalid");genesis::Expression e{"rna","gene","cell","genome",.5,1};check(genesis::transition(e,genesis::RnaState::expressing),"RNA express");check(genesis::transition(e,genesis::RnaState::consumed),"RNA consume");check(genesis::transition(e,genesis::RnaState::removed),"RNA remove");check(!genesis::transition(e,genesis::RnaState::expressing),"RNA revived");genesis::MaturityVector m;m.scores.fill(95);check(genesis::independence_gate(m),"independence rejected");m.scores[static_cast<std::size_t>(genesis::Dimension::security)]=50;check(!genesis::independence_gate(m),"unsafe independence");std::cout<<"All Genesis tests passed\n";return EXIT_SUCCESS;}catch(const std::exception&e){std::cerr<<"FAIL: "<<e.what()<<'\n';return EXIT_FAILURE;}}
